/**
 * Worker entry: the OpenNext (Next.js) handler plus ONE daily cron (free Cron Trigger, 12:00 UTC = 09:00 Buenos Aires):
 *  - one push per user for invoices that just became overdue (lib/documents-push.ts),
 *  - creation of due recurring movements (lib/recurring.ts, idempotent) and purge of receipts never attached to a movement.
 * Each job runs on its own: one failing does not stop the other.
 */
// Generated by `opennextjs-cloudflare build`; it may or may not exist when `next build` type-checks this file.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";
import { notifyOverdueInvoices } from "./lib/documents-push.ts";
import { todayBA } from "./lib/agenda-dates.ts";
import { generateDue, todayInBuenosAires } from "./lib/recurring.ts";
import { purgeOrphanReceipts } from "./lib/receipts-db.ts";

type Env = { DB: Parameters<typeof notifyOverdueInvoices>[0] & Parameters<typeof generateDue>[0] & Parameters<typeof purgeOrphanReceipts>[0]; VAPID_PUBLIC_KEY?: string; VAPID_PRIVATE_KEY?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };
const ADMIN_EMAIL = "lucianoolivabianco@gmail.com"; // VAPID subject; same value as lib/auth.ts (not imported: it pulls Better Auth into the cron)

async function overdueInvoices(env: Env, now: Date) {
  if (!env.VAPID_PUBLIC_KEY || !env.VAPID_PRIVATE_KEY) return null;
  return notifyOverdueInvoices(env.DB, todayBA(now), { publicKey: env.VAPID_PUBLIC_KEY, privateKey: env.VAPID_PRIVATE_KEY, subject: `mailto:${ADMIN_EMAIL}` });
}

async function recurringAndReceipts(env: Env, now: Date) {
  const result = await generateDue(env.DB, null, todayInBuenosAires(now.getTime()));
  const purged = await purgeOrphanReceipts(env.DB, now.getTime());
  console.log("cron_recurring_done", { rules: result.rules, created: result.created, purgedReceipts: purged });
  return result;
}

async function runDailyJobs(env: Env, now = new Date()) {
  const jobs: [string, () => Promise<unknown>][] = [["overdue_invoices", () => overdueInvoices(env, now)], ["recurring_and_receipts", () => recurringAndReceipts(env, now)]];
  for (const [name, job] of jobs) {
    try { await job(); } catch (error) { console.error("cron_job_failed", { job: name, error: String(error) }); }
  }
}

const worker = {
  fetch(request: Request, env: unknown, ctx: unknown) {
    return handler.fetch(request, env, ctx);
  },
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    ctx.waitUntil(runDailyJobs(env));
  },
};

export default worker;
